n = int(input())
data = set(input().split())
temp = 'RGBYW'
c = []
res = 10
for i in data:
	p1 = temp.find(i[0])
	p2 = int(i[1]) - 1
	c.append(2 ** p1 + 2 ** (p2 + 5))
for i in range(1024):
	ok = True
	for j in range(len(c) - 1):
		for k in range(j + 1, len(c)):
			if c[j] & i == c[k] & i:
				ok = False
	if ok:
		tt = 0
		inow = i
		while inow != 0:
			tt += inow % 2
			inow //= 2
		res = min(res, tt)
print(res)
